let A = "<Am9 Am9 F^7 F^7 C^7 C^7 G G>"
let B = "<F^7 F^7 C^7 C^7 Dm7 Dm7 Em7 Em7>"
let C = "<Am9 Am9 Dm7 Dm7 F^7 F^7 Em7 Em7>"
